const TrendChart = lazy(() => import('./TrendChart'));
function usePageUni() { return useOutletContext<{ university: University }>().university; }
function PendingNote() { return <div className="preview-note"><SampleBadge/><br/><strong>Sample preview.</strong> This is sample data so you can see what your dashboard will show. Write actions are available after approval.</div>; }
function LoadBlock() { return <div className="page-loading"><Spinner/></div>; }
function PageWrap({ children }: { children: React.ReactNode }) { return <div className="page">{env.useMocks?<div className="page-sample"><SampleBadge/></div>:null}{children}</div>; }
function FocusTrap({children,onClose}:{children:React.ReactNode;onClose:()=>void}) {
  const root=useRef<HTMLDivElement|null>(null);const closeRef=useRef(onClose);closeRef.current=onClose;
  useEffect(()=>{const node=root.current;if(!node)return;const previous=document.activeElement instanceof HTMLElement?document.activeElement:null;const getItems=()=>Array.from(node.querySelectorAll<HTMLElement>('button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),a[href],[tabindex]:not([tabindex="-1"])'));getItems()[0]?.focus();const onKey=(event:KeyboardEvent)=>{if(event.key==='Escape'){event.preventDefault();closeRef.current();return;}if(event.key==='Tab'){const items=getItems();if(!items.length){event.preventDefault();return;}const first=items[0]!;const last=items[items.length-1]!;if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}};node.addEventListener('keydown',onKey);return()=>{node.removeEventListener('keydown',onKey);previous?.focus();};},[]);
  return <div className="modal-backdrop" role="presentation" ref={root} onMouseDown={(event)=>{if(event.target===event.currentTarget)closeRef.current();}}>{children}</div>;
}

function Funnel({ counts }: { counts: { invited: number; registered: number; submitted: number; verified: number } }) {
  const rows = funnelRows(counts); const drop = largestFunnelDrop(counts);
  return <div className="funnel" role="table" aria-label="Activation funnel">{rows.map((row) => <div className="funnel-row" role="row" aria-label={`${row.label}: ${row.count}; ${row.conversion}`} key={row.label}><span className="funnel-label" role="cell">{row.label}</span><span className="funnel-count tabular" role="cell">{row.count}</span><div className="funnel-track" role="presentation"><div className="funnel-bar" style={{ width: row.width, background: row.color }}/></div><span className="funnel-conversion" role="cell">{row.conversion}</span></div>)}<p className="funnel-drop">The biggest drop is between {drop.from} and {drop.to}. {drop.count} students {`haven’t ${drop.next} yet.`}</p></div>;
}
function SkillTable({ skills, compact = false }: { skills: { id: string; name: string; family: string; verified_students: number; assessed_students: number; avg_score: number; open_jobs: number }[]; compact?: boolean }) {
  return <div className="skills-overflow"><table className="skills-table"><caption className="sr-only">Verified skills and demand</caption><thead><tr><th scope="col">Skill</th>{!compact ? <th scope="col">Family</th> : null}<th scope="col">Verified students</th>{!compact ? <th scope="col">Assessed</th> : null}<th scope="col">Average score</th><th scope="col">Open jobs</th></tr></thead><tbody>{skills.map((skill) => <tr key={skill.id}><td><strong>{skill.name}</strong></td>{!compact ? <td>{skill.family}</td> : null}<td className="tabular">{skill.verified_students}</td>{!compact ? <td className="tabular">{skill.assessed_students}</td> : null}<td>{skill.avg_score} · {levelFor(skill.avg_score)}</td><td className="tabular">{skill.open_jobs}</td></tr>)}</tbody></table></div>;
}
function DemandPreview({ rows }: { rows: DemandRow[] }) {
  return <div>{rows.slice(0,5).map((row) => <div className="demand-row" key={row.id}><div className="demand-title"><div><h3>{row.skill_name}</h3><p>{row.jobs_count} {row.jobs_count === 1 ? 'job' : 'jobs'} · Last posted {new Date(row.last_posted_at).toLocaleDateString('en-IN', { day: 'numeric', month: 'short' })}</p></div><span className="chip chip-pending">Demand</span></div><ReasonBar row={row} compact/></div>)}</div>;
}
function ReasonBar({ row, compact = false }: { row: DemandRow; compact?: boolean }) {
  const labels: [string,string][] = [['no_eligible','No eligible candidates'],['incomplete_assessments','Incomplete assessments'],['insufficient_evidence','Insufficient evidence'],['skills_mismatch','Skills mismatch'],['opted_out','Opted out'],['not_assessed','Not yet assessed']];
  const reasonLabels = labels.map(([key,label]) => ({ key,label,count: row.reasons[key] ?? 0 })).sort((a,b) => b.count-a.count);
  const total = reasonLabels.reduce((sum,item)=>sum+item.count,0) || 1;
  const largest = reasonLabels[0]?.key ?? 'not_assessed';
  const suggestions: Record<string,string> = {
    not_assessed: 'Many students haven’t been assessed yet. Encourage them to submit a project in this skill.',
    incomplete_assessments: 'Students started but didn’t finish. A short workshop may help.',
    insufficient_evidence: 'Reviews lacked evidence. Remind students to include a demo video and clear README.',
    skills_mismatch: 'Students’ verified skills differ from this job. Consider this skill for your curriculum.',
    no_eligible: 'No students are verified in this skill yet.',
    opted_out: 'Some students have chosen not to be discoverable. Remind them what discovery means: employers see skills, not names.'
  };
  return <div className="reason-box"><div className="reason-stack" aria-label={`${row.skill_name} demand reasons`}>{reasonLabels.map((item) => <div key={item.key} className="reason-segment" style={{ width: `${item.count / total * 100}%` }} title={`${item.label}: ${item.count}`}/>)}</div><div className="reason-legend">{reasonLabels.filter((item)=>item.count>0).map((item) => <span className="reason-key" key={item.key}><span className="reason-dot"/>{item.label}: {item.count}</span>)}</div>{!compact ? <p className="suggestion">{suggestions[largest]}</p> : null}</div>;
}
function useExport() {
  const [rows, setRows] = useState<Record<string, unknown>[] | null>(null); const [title, setTitle] = useState('students'); const university = usePageUni();
  const prepare = (kind: string, data: Record<string, unknown>[]) => { setTitle(kind); setRows(data); };
  const download = () => {
    if (!rows) return;
    const fields = Object.keys(rows[0] ?? {}); const safe = rows.map((row) => Object.fromEntries(fields.map((field) => [field, safeCsvCell(row[field])])));
    const csv = `\uFEFF${Papa.unparse(safe, { columns: fields })}`; const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8' })); const anchor = document.createElement('a'); anchor.href = url; anchor.download = `aptohire-${title}-${university.short_name.toLowerCase()}-${new Date().toISOString().slice(0,10)}.csv`; anchor.click(); URL.revokeObjectURL(url); setRows(null);
  };
  const dialog = rows ? <FocusTrap onClose={()=>setRows(null)}><section className="modal" role="dialog" aria-modal="true" aria-labelledby="export-title"><h2 id="export-title">Before you download</h2><p className="file-warning">This file contains student names. Store it securely and delete it when you’re done.</p><div className="modal-actions"><Button variant="secondary" onClick={() => setRows(null)}>Cancel</Button><Button onClick={download}><Download size={17}/>Download</Button></div></section></FocusTrap> : null;
  return { prepare, dialog };
}
export function OverviewPage() {
  const uni = usePageUni(); const query = useOverview(); const demand = useDemand(); const [tableView,setTableView]=useState(false); const [searchParams,setSearchParams]=useSearchParams(); const year=searchParams.get('year')??''; const program=searchParams.get('program')??''; const cohortStatus=searchParams.get('status')??''; const setCohort=(key:string,value:string)=>{const next=new URLSearchParams(searchParams);if(value)next.set(key,value);else next.delete(key);setSearchParams(next,{replace:true});};
  const overview = query.data; const pending=uni.status==='pending'; const trendRef=useRef<HTMLElement|null>(null); const [chartVisible,setChartVisible]=useState(false); useEffect(()=>{const node=trendRef.current;if(!node)return;const observer=new IntersectionObserver((entries)=>{if(entries.some((entry)=>entry.isIntersecting)){setChartVisible(true);observer.disconnect();}});observer.observe(node);return()=>observer.disconnect();},[overview?.trends.length]);
  if (query.isPending) return <LoadBlock/>;
  if (query.isError || !overview) return <PageWrap><ErrorState onRetry={() => void query.refetch()}/></PageWrap>;
  const funnel={...overview.funnel};
  const hasCohortFilter=Boolean(year||program||cohortStatus);
  const cohortRows=(overview.funnel_rows??[]).filter((row)=>(!year||String(row.year)===year)&&(!program||row.program===program)&&(!cohortStatus||row.status===cohortStatus));
  const filteredFunnel=hasCohortFilter&&overview.funnel_rows?cohortRows.reduce((total,row)=>({invited:total.invited+row.invited,registered:total.registered+row.registered,submitted:total.submitted+row.submitted,verified:total.verified+row.verified}),{invited:0,registered:0,submitted:0,verified:0}):funnel;
  return <PageWrap><div className="hero-panel"><div><div className="hero-meta"><Chip tone={uni.status==='approved'?'approved':'pending'}>{uni.status==='approved'?'Approved':'Pending application'}</Chip>{pending?<SampleBadge/>:null}</div><h1>{uni.name}</h1><p>{pending ? 'A sample of the student progress dashboard.' : `${overview.students_total} students on your roster. ${overview.verified_students} have a verified skill.`}</p></div><div className="hero-detail"><span>{uni.city}, {uni.state}</span><span>{uni.tier} · {uni.kind}</span></div></div>{pending?<PendingNote/>:null}
    <StatRow items={[{label:'Verified students',value:overview.verified_students},{label:'Active this month',value:overview.active_this_month},{label:'Projects reviewed',value:overview.projects_reviewed},{label:'Students on roster',value:overview.students_total}]}/>
    <div className="filter-row cohort-filters" aria-label="Cohort filters"><strong className="filter-heading">Cohort</strong><label className="sr-only" htmlFor="cohort-year">Year</label><select id="cohort-year" className="filter-select" value={year} onChange={(event)=>setCohort('year',event.target.value)}><option value="">All years</option>{[1,2,3,4,5].map((value)=><option key={value} value={value}>{value} year</option>)}</select><label className="sr-only" htmlFor="cohort-program">Program</label><select id="cohort-program" className="filter-select" value={program} onChange={(event)=>setCohort('program',event.target.value)}><option value="">All programs</option><option>Computer Science</option><option>Information Technology</option><option>Data Science</option></select><label className="sr-only" htmlFor="cohort-status">Status</label><select id="cohort-status" className="filter-select" value={cohortStatus} onChange={(event)=>setCohort('status',event.target.value)}><option value="">All statuses</option><option value="enrolled">Enrolled</option><option value="incoming">Incoming</option><option value="alumni">Alumni</option></select>{year||program||cohortStatus?<button className="button button-ghost" onClick={()=>setSearchParams({}, {replace:true})}>Clear filters</button>:null}</div>
    <section className="section"><div className="section-header"><div><h2>Activation funnel</h2><p className="section-note">Follow the steps from invitation to verified skills.</p></div>{pending?<SampleBadge/>:null}</div><Funnel counts={filteredFunnel}/></section>
    <section className="section"><div className="section-header"><div><h2>Skills</h2><p className="section-note">Verified results only. Reviews under human review are excluded. Skill totals are university-wide.</p></div><Link className="text-link" to="/skills?tab=supply">See all skills <ChevronRight size={16}/></Link></div><SkillTable skills={overview.skills.slice(0,8)} compact/></section>
    <section className="section"><div className="section-header"><div><h2>Unmatched demand</h2><p className="section-note">Skills requested in jobs without enough matching candidates.</p></div><Link className="text-link" to="/skills?tab=unmatched">See demand <ChevronRight size={16}/></Link></div>{demand.isPending?<Spinner/>:demand.isError?<ErrorState onRetry={()=>void demand.refetch()}/>:<DemandPreview rows={demand.data??[]}/>}</section>
    <section className="section" ref={trendRef}><div className="section-header"><div><h2>Your trends</h2><p className="section-note">Your own trends. AptoHire doesn’t compare universities or publish rankings.</p></div><div className="chart-switch"><button className={`switch-button${!tableView?' active':''}`} onClick={()=>setTableView(false)}>Chart</button><button className={`switch-button${tableView?' active':''}`} onClick={()=>setTableView(true)}>View as table</button></div></div>{overview.trends.length<3?<p className="muted">Trends appear after a few weeks of activity.</p>:tableView?<div className="table-wrap"><table className="data-table"><caption className="sr-only">University trends over time</caption><thead><tr><th scope="col">Week</th><th scope="col">Verified students</th><th scope="col">Reviews</th></tr></thead><tbody>{overview.trends.slice(-8).map((row)=><tr key={row.week_start}><td>{new Date(row.week_start).toLocaleDateString('en-IN',{day:'numeric',month:'short'})}</td><td>{row.verified_total}</td><td>{row.reviews}</td></tr>)}</tbody></table></div>:chartVisible?<Suspense fallback={<div className="skeleton" style={{height:240}}/>}><TrendChart data={overview.trends}/></Suspense>:<div className="skeleton" style={{height:240}} aria-label="Trend chart loads when visible"/>}</section>
  </PageWrap>;
}
function statusChip(status: Student['status']) { const label: Record<Student['status'],string>={incoming:'Incoming',enrolled:'Enrolled',dropout:'Dropout',alumni:'Alumni'}; return <Chip tone={status==='enrolled'?'enrolled':status==='dropout'?'dropout':'muted'}>{label[status]}</Chip>; }
function VerificationChip({ student }: { student: Student }) { if (!student.claimed) return <Chip tone="muted">Unverified</Chip>; if (student.verification==='roster') return <Chip tone="roster"><ShieldCheck size={14}/>Verified via roster</Chip>; if (student.verification==='student_id') return <Chip tone="roster"><ShieldCheck size={14}/>Verified via student ID</Chip>; return <Chip tone="outline">Unverified</Chip>; }
function PlacementChip({ status }: { status: Student['placement_status'] }) { if(status==='placed')return <Chip tone="verified"><Check size={14}/>Placed</Chip>;if(status==='not_placed')return <Chip tone="muted">Not placed</Chip>;return <Chip tone="outline">Unknown</Chip>; }
function ExportButton({ onClick }: { onClick: () => void }) { return <Button variant="secondary" onClick={onClick}><Download size={17}/>Export CSV</Button>; }
export function StudentsPage() {
  const query=useStudents();const [search,setSearch]=useState('');const [year,setYear]=useState('');const [status,setStatus]=useState('');const [registered,setRegistered]=useState('');const [hasSkill,setHasSkill]=useState(false);const [selected,setSelected]=useState<Student|null>(null);const [toast,setToast]=useState('');const {prepare,dialog}=useExport();const uni=usePageUni();
  const filtered=useMemo(()=> (query.data??[]).filter((s)=>s.full_name.toLowerCase().includes(search.toLowerCase())||(s.email??'').toLowerCase().includes(search.toLowerCase())).filter((s)=>!year||String(s.year)===year).filter((s)=>!status||s.status===status).filter((s)=>!registered||(registered==='yes'?s.claimed:!s.claimed)).filter((s)=>!hasSkill||s.verified_skills_count>0),[query.data,search,year,status,registered,hasSkill]);
  if(query.isPending)return <LoadBlock/>;if(query.isError)return <PageWrap><ErrorState onRetry={()=>void query.refetch()}/></PageWrap>;
  const openStudent=(student:Student)=>{if(student.claimed)window.location.assign(`/students/${student.id}`);else setSelected(student);};
  const exportRows=filtered.map((s)=>({Name:s.full_name,Status:s.status,Verification:s.verification??'unverified',Registered:s.claimed?'Yes':'No','Verified skills':s.verified_skills_count,'Last activity':s.last_activity??'',Placement:s.placement_status}));
  return <PageWrap><PageTitle title="Students" description="Roster is your list. This page shows how each student is doing on AptoHire." actions={<ExportButton onClick={()=>prepare('students',exportRows)}/>}/>{uni.status==='pending'?<PendingNote/>:null}<div className="filter-row"><div className="searchbox"><Search size={18}/><label className="sr-only" htmlFor="student-search">Search students</label><input className="input" id="student-search" placeholder="Search by name or email" value={search} onChange={(e)=>setSearch(e.target.value)}/></div><select aria-label="Filter by year" className="filter-select" value={year} onChange={(e)=>setYear(e.target.value)}><option value="">All years</option>{[1,2,3,4].map((n)=><option key={n} value={n}>{n} year</option>)}</select><select aria-label="Filter by status" className="filter-select" value={status} onChange={(e)=>setStatus(e.target.value)}><option value="">All statuses</option>{['incoming','enrolled','dropout','alumni'].map((x)=><option key={x} value={x}>{x}</option>)}</select><select aria-label="Filter registration" className="filter-select" value={registered} onChange={(e)=>setRegistered(e.target.value)}><option value="">All registration</option><option value="yes">Registered</option><option value="no">Not registered</option></select><label className="filter-checkbox"><input type="checkbox" checked={hasSkill} onChange={(e)=>setHasSkill(e.target.checked)}/> Has a verified skill</label></div><p className="result-count" aria-live="polite">{filtered.length} students</p>
    {filtered.length===0?<EmptyState title="No students match these filters."/>:<><div className="table-wrap"><table className="data-table"><caption className="sr-only">Students and verified skills</caption><thead><tr>{['Name','Status','Verification','Registered','Verified skills','Last activity','Placement'].map((label)=><th scope="col" key={label}>{label}</th>)}</tr></thead><tbody>{filtered.slice(0,25).map((s)=><tr key={s.id} className={s.claimed?'clickable-row':''} onClick={()=>openStudent(s)} tabIndex={0} onKeyDown={(e)=>{if(e.key==='Enter')openStudent(s);}}><td className="table-name">{s.full_name}<span className="block muted">{s.program??'Program not listed'} · {s.year?`Year ${s.year}`:'Year not listed'}</span></td><td>{statusChip(s.status)}</td><td><VerificationChip student={s}/></td><td>{s.claimed?<Chip tone="roster"><Check size={14}/>Registered</Chip>:<Chip tone="muted">Not registered yet</Chip>}</td><td className="tabular">{s.verified_skills_count}</td><td>{s.last_activity?new Date(s.last_activity).toLocaleDateString('en-IN',{day:'numeric',month:'short'}):'—'}</td><td><PlacementChip status={s.placement_status}/></td></tr>)}</tbody></table><div className="table-mobile">{filtered.slice(0,25).map((s)=><button className="table-mobile-row mobile-student" key={s.id} onClick={()=>openStudent(s)}><strong>{s.full_name}</strong><div className="table-mobile-line"><span>Status</span><span>{s.status}</span></div><div className="table-mobile-line"><span>Verification</span><span>{s.claimed?s.verification:'Unverified'}</span></div><div className="table-mobile-line"><span>Registered</span><span>{s.claimed?'Yes':'No'}</span></div><div className="table-mobile-line"><span>Verified skills</span><span>{s.verified_skills_count}</span></div></button>)}</div></div><p className="small muted">Showing 1–{Math.min(25,filtered.length)} of {filtered.length} students</p></>}
    {selected?<FocusTrap onClose={()=>setSelected(null)}><section className="modal" role="dialog" aria-modal="true" aria-labelledby="unregistered-title"><button className="modal-close icon-button" onClick={()=>setSelected(null)} aria-label="Close"><X/></button><h2 id="unregistered-title">{selected.full_name}</h2><p>{selected.program??'Program not listed'} · {selected.year?`Year ${selected.year}`:'Year not listed'}</p><p>Hasn’t registered on AptoHire yet.</p><Button onClick={async()=>{await navigator.clipboard?.writeText(portalUrl('student','/signup'));setToast('Sign-up link copied.');setSelected(null);window.setTimeout(()=>setToast(''),3000);}}><Copy size={16}/>Copy sign-up link</Button></section></FocusTrap>:null}{dialog}{toast?<div className="toast" role="status">{toast}</div>:null}</PageWrap>;
}
export function StudentDetailPage() {
  const {studentId=''}=useParams();const backend=useBackend();const uni=usePageUni();const config=useQuery({queryKey:['public-config'],queryFn:()=>backend.config.getPublic()});const query=useQuery({queryKey:['student',uni.id,studentId],queryFn:()=>backend.students.detail(studentId)});const skills=useQuery({queryKey:['student-skills',uni.id,studentId],queryFn:()=>backend.students.skills(studentId),enabled:!query.isPending&&Boolean(query.data)});
  if(query.isPending)return <LoadBlock/>;if(query.isError||!query.data)return <PageWrap><PageTitle title="Student details"/><EmptyState title="This student isn’t available in your university roster." action="Back to students" onAction={()=>window.location.assign('/students')}/></PageWrap>;
  const student=query.data;return <PageWrap><Link className="back-link" to="/students">← Back to students</Link><div className="detail-header"><div><PageTitle title={student.full_name} description={`${student.program??'Program not listed'} · ${student.year?`Year ${student.year}`:'Year not listed'}`}/><div className="hero-meta">{statusChip(student.status)}<VerificationChip student={student}/><span className="small muted">{student.claimed?'Registered':'Not registered yet'}</span></div></div></div><section className="section"><h2>Verified skills</h2>{skills.isPending?<Spinner/>:skills.data?.length?skills.data.map((skill)=>{const verified=isVerified(skill.score,config.data?.passMark??PASS_MARK_FALLBACK);return <div className="skill-proof" key={skill.skill_name}><svg className="proof-ring" viewBox="0 0 56 56" role="img" aria-label={proofAriaLabel(skill.skill_name,skill.score,skill.level,verified)}><circle cx="28" cy="28" r="23" fill="none" stroke="var(--hairline)" strokeWidth="5"/><circle cx="28" cy="28" r="23" fill="none" stroke="var(--verdant-600)" strokeWidth="5" strokeLinecap="round" strokeDasharray={`${skill.score/100*144.5} 144.5`} transform="rotate(-90 28 28)"/><text x="28" y="32" textAnchor="middle" fontSize="13" fontWeight="700" fill="var(--ink)">{skill.score}</text></svg><div><strong>{skill.skill_name}</strong><div className="small muted">{skill.level} · Verified on {new Date(skill.verified_on).toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'})}</div></div><Chip tone="verified"><BadgeCheck size={14}/>Verified</Chip></div>}):<p className="muted">No verified skills yet.</p>}</section><section className="section"><h2>Scorecard summary</h2><StatRow items={[{label:'Verified skills',value:student.verified_skills_count},{label:'Projects reviewed',value:student.verified_skills_count?student.verified_skills_count+2:0},{label:'Strongest skill',value:skills.data?.[0]?.skill_name??'—'}]}/></section><section className="section"><h2>Placement</h2><p><PlacementChip status={student.placement_status}/></p><Link to="/placements" className="text-link">View placements <ChevronRight size={16}/></Link></section><div className="privacy-note"><LockKeyhole size={17}/>Project files and videos are private to the student.</div></PageWrap>;
}
export function RosterPage() {
  const uni=usePageUni();const backend=useBackend();const query=useQuery({queryKey:['roster',uni.id],queryFn:()=>backend.roster.list()});const client=useQueryClient();const [search,setSearch]=useState('');const [toast,setToast]=useState('');const [addOpen,setAddOpen]=useState(false);const [editStudent,setEditStudent]=useState<Student|null>(null);const [confirmStatus,setConfirmStatus]=useState<{student:Student;status:'dropout'|'alumni'}|null>(null);const {prepare,dialog}=useExport();
  if(query.isPending)return <LoadBlock/>;if(query.isError)return <PageWrap><ErrorState onRetry={()=>void query.refetch()}/></PageWrap>;
  const students=(query.data??[]).filter((s)=>s.full_name.toLowerCase().includes(search.toLowerCase())||(s.email??'').toLowerCase().includes(search.toLowerCase()));
  const exportRows=students.map((s)=>({Name:s.full_name,Email:s.email??'',Program:s.program??'',Year:s.year??'',Status:s.status,Registered:s.claimed?'Yes':'No'}));
  const update=async(student:Student,status:'dropout'|'alumni')=>{await backend.roster.update(student.id,{status});await client.invalidateQueries({queryKey:['roster']});setToast(`Marked as ${status==='alumni'?'alumni':'dropout'}.`);window.setTimeout(()=>setToast(''),3000);};
  return <PageWrap><PageTitle title="Roster" description="Roster is your master list. Changes here update how a student appears on AptoHire—not your university’s own records." actions={<><ExportButton onClick={()=>prepare('roster',exportRows)}/><Link className={`button ${students.length===0?'button-accent':'button-primary'}`} to="/roster/import"><FileUp size={17}/>Upload roster</Link><button className="button button-secondary" onClick={()=>setAddOpen(true)}>Add a student</button></>}/>{uni.status==='pending'?<PendingNote/>:null}<p className="privacy-note"><Info size={17}/>We store only a secure fingerprint of student IDs, never the numbers themselves.</p><div className="filter-row"><div className="searchbox"><Search size={18}/><label className="sr-only" htmlFor="roster-search">Search roster</label><input id="roster-search" className="input" placeholder="Search by name or email" value={search} onChange={(e)=>setSearch(e.target.value)}/></div><p aria-live="polite" className="muted">{students.length} students</p></div>{students.length===0?<EmptyState title="Add your students to get started. Upload a CSV with name, email, and year." action="Upload roster" onAction={()=>window.location.assign('/roster/import')}/>:<div className="table-wrap"><table className="data-table"><caption className="sr-only">Roster</caption><thead><tr>{['Name','Email','Program','Year','Status','Registered','Actions'].map((x)=><th scope="col" key={x}>{x}</th>)}</tr></thead><tbody>{students.slice(0,25).map((s)=><tr key={s.id}><td className="table-name">{s.full_name}</td><td>{s.email??'—'}</td><td>{s.program??'—'}</td><td>{s.year??'—'}</td><td>{statusChip(s.status)}</td><td>{s.claimed?'Registered':'Not registered'}</td><td><div className="table-actions"><button className="button button-ghost compact-action" disabled={uni.status==='pending'} title={uni.status==='pending'?'Available after approval':''} onClick={()=>setEditStudent(s)}>Edit</button><button className="button button-ghost compact-action" disabled={uni.status==='pending'} title={uni.status==='pending'?'Available after approval':''} onClick={()=>setConfirmStatus({student:s,status:'alumni'})}>Mark alumni</button><button className="button button-ghost compact-action" disabled={uni.status==='pending'} title={uni.status==='pending'?'Available after approval':''} onClick={()=>setConfirmStatus({student:s,status:'dropout'})}>Mark dropout</button>{!s.claimed?<button className="button button-danger compact-action" disabled={uni.status==='pending'} title={uni.status==='pending'?'Available after approval':''} onClick={async()=>{await backend.roster.remove(s.id);await client.invalidateQueries({queryKey:['roster']});}}>Remove</button>:<span className="small muted">Registered students can’t be removed; mark as alumni or dropout.</span>}</div></td></tr>)}</tbody></table><div className="table-mobile">{students.slice(0,25).map((s)=><div className="table-mobile-row" key={s.id}><strong>{s.full_name}</strong><div className="table-mobile-line"><span>Email</span><span>{s.email??'—'}</span></div><div className="table-mobile-line"><span>Program / year</span><span>{s.program??'—'} · {s.year??'—'}</span></div><div className="table-mobile-line"><span>Status</span><span>{s.status}</span></div><div className="table-actions"><button className="button button-secondary" disabled={uni.status==='pending'} onClick={()=>setConfirmStatus({student:s,status:'alumni'})}>Mark alumni</button><button className="button button-secondary" disabled={uni.status==='pending'} onClick={()=>setConfirmStatus({student:s,status:'dropout'})}>Mark dropout</button></div></div>)}</div></div>}{addOpen?<AddStudentDialog close={()=>setAddOpen(false)} saved={async(row)=>{await backend.roster.importRows([row],false);await client.invalidateQueries({queryKey:['roster']});setAddOpen(false);setToast('Student added.');window.setTimeout(()=>setToast(''),3000);}}/>:null}{editStudent?<EditRosterDialog student={editStudent} close={()=>setEditStudent(null)} saved={async(patch)=>{await backend.roster.update(editStudent.id,patch);await client.invalidateQueries({queryKey:['roster']});setEditStudent(null);setToast('Student updated.');window.setTimeout(()=>setToast(''),3000);}}/>:null}{confirmStatus?<FocusTrap onClose={()=>setConfirmStatus(null)}><section className="modal" role="dialog" aria-modal="true" aria-labelledby="confirm-status-title"><h2 id="confirm-status-title">Mark as {confirmStatus.status}?</h2><p>This changes how the student appears on AptoHire. Their scores and credential don’t change.</p><div className="modal-actions"><Button variant="secondary" onClick={()=>setConfirmStatus(null)}>Cancel</Button><Button onClick={async()=>{await update(confirmStatus.student,confirmStatus.status);setConfirmStatus(null);}}>Mark as {confirmStatus.status}</Button></div></section></FocusTrap>:null}{dialog}{toast?<div className="toast" role="status">{toast}</div>:null}</PageWrap>;
}
function AddStudentDialog({close,saved}:{close:()=>void;saved:(row:CanonicalRow)=>Promise<void>}) {
  const [error,setError]=useState('');const [busy,setBusy]=useState(false);
  return <FocusTrap onClose={close}><form className="modal roster-form" role="dialog" aria-modal="true" aria-labelledby="add-student-title" onSubmit={async(event)=>{event.preventDefault();setError('');const form=new FormData(event.currentTarget);const email=String(form.get('email')??'').trim();const id=String(form.get('student_id_number')??'').trim();if(!email&&!id){setError('Add an email or student ID so this student can be matched.');return;}const yearRaw=String(form.get('year')??'');const raw={full_name:String(form.get('full_name')??'').trim(),email,student_id_number:id,program:String(form.get('program')??'').trim(),program_level:String(form.get('program_level')??'ug'),year:yearRaw?Number(yearRaw):undefined,status:String(form.get('status')??'enrolled')};const parsed=rosterRowSchema.safeParse(raw);if(!parsed.success){setError('Check the student details and try again.');return;}setBusy(true);try{await saved(parsed.data);}catch{setError('We couldn’t add this student. Check your connection and try again.');}finally{setBusy(false);}}}><button type="button" className="modal-close icon-button" aria-label="Close add student" onClick={close}><X/></button><h2 id="add-student-title">Add a student</h2><p>We use an email or student ID to match students when they sign up.</p>{error?<div className="error-message" role="alert">{error}</div>:null}<label className="field"><span>Name · required</span><input name="full_name" required minLength={2}/></label><label className="field"><span>Email</span><input name="email" type="email" autoComplete="email"/></label><label className="field"><span>Student ID</span><input name="student_id_number"/></label><label className="field"><span>Program</span><input name="program"/></label><div className="field-two"><label className="field"><span>Program level</span><select name="program_level"><option value="ug">Undergraduate</option><option value="pg">Postgraduate</option></select></label><label className="field"><span>Year</span><select name="year"><option value="">Not listed</option>{[1,2,3,4,5,6,7].map((year)=><option key={year}>{year}</option>)}</select></label></div><label className="field"><span>Lifecycle status</span><select name="status"><option value="enrolled">Enrolled</option><option value="incoming">Incoming</option><option value="dropout">Dropout</option><option value="alumni">Alumni</option></select></label><div className="modal-actions"><Button type="button" variant="secondary" onClick={close}>Cancel</Button><Button type="submit" loading={busy}>Add a student</Button></div></form></FocusTrap>;
}
function EditRosterDialog({student,close,saved}:{student:Student;close:()=>void;saved:(patch:Partial<Pick<Student,'year'|'program'|'program_level'|'status'>>)=>Promise<void>}) {
  const [busy,setBusy]=useState(false);const [status,setStatus]=useState<Student['status']>(student.status);const [error,setError]=useState('');
  return <FocusTrap onClose={close}><form className="modal roster-form" role="dialog" aria-modal="true" aria-labelledby="edit-roster-title" onSubmit={async(event)=>{event.preventDefault();setBusy(true);setError('');const form=new FormData(event.currentTarget);const yearRaw=String(form.get('year')??'');const patch={year:yearRaw?Number(yearRaw):null,program:String(form.get('program')??'').trim()||null,program_level:String(form.get('program_level')??'ug') as 'ug'|'pg',status};try{await saved(patch);}catch{setError('We couldn’t update this student. Check your connection and try again.');}finally{setBusy(false);}}}><button type="button" className="modal-close icon-button" aria-label="Close edit student" onClick={close}><X/></button><h2 id="edit-roster-title">Edit {student.full_name}</h2><p>Name, email and student ID can’t be edited here.</p>{error?<div className="error-message" role="alert">{error}</div>:null}<label className="field"><span>Year</span><select name="year" defaultValue={student.year??''}><option value="">Not listed</option>{[1,2,3,4,5,6,7].map((year)=><option value={year} key={year}>{year}</option>)}</select></label><label className="field"><span>Program</span><input name="program" defaultValue={student.program??''}/></label><label className="field"><span>Program level</span><select name="program_level" defaultValue={student.program_level}><option value="ug">Undergraduate</option><option value="pg">Postgraduate</option></select></label><label className="field"><span>Lifecycle status</span><select value={status} onChange={(event)=>setStatus(event.target.value as Student['status'])}><option value="incoming">Incoming</option><option value="enrolled">Enrolled</option><option value="dropout">Dropout</option><option value="alumni">Alumni</option></select></label>{status==='dropout'||status==='alumni'?<p className="preview-note">This changes how the student appears on AptoHire. Their scores and credential don’t change.</p>:null}<div className="modal-actions"><Button type="button" variant="secondary" onClick={close}>Cancel</Button><Button type="submit" loading={busy}>Save changes</Button></div></form></FocusTrap>;
}

function invalidRowCount(errors: { row: number; field: string; reason: string }[]) { return new Set(errors.map((item)=>item.row)).size; }
function downloadErrors(errors: { row: number; field: string; reason: string }[]) {
  const url=URL.createObjectURL(new Blob([`\uFEFF${Papa.unparse(errors)}`],{type:'text/csv;charset=utf-8'}));const anchor=document.createElement('a');anchor.href=url;anchor.download='aptohire-roster-errors.csv';anchor.click();URL.revokeObjectURL(url);
}
export function ImportPage() {
  const uni=usePageUni();const backend=useBackend();const client=useQueryClient();const navigate=useNavigate();
  const [step,setStep]=useState(1);const [file,setFile]=useState<File|null>(null);const [text,setText]=useState('');const [headers,setHeaders]=useState<string[]>([]);const [columnMap,setColumnMap]=useState<Record<string,string>>({});const [rows,setRows]=useState<CanonicalRow[]>([]);const [errors,setErrors]=useState<{row:number;field:string;reason:string}[]>([]);const [report,setReport]=useState<ImportReport|null>(null);const [serverReport,setServerReport]=useState<ImportReport|null>(null);const [busy,setBusy]=useState(false);const [error,setError]=useState('');
  const chooseFile=async(input:File|null)=>{setError('');if(!input)return;if(!input.name.toLowerCase().endsWith('.csv')||!['text/csv','application/vnd.ms-excel',''].includes(input.type)){setError('This doesn’t look like a CSV file. Save your sheet as CSV (UTF-8) and try again. Excel files (.xlsx) aren’t supported. Save as CSV.');return;}if(input.size>env.rosterMaxMb*1024*1024){setError(`This file is ${(input.size/1024/1024).toFixed(1)} MB. The limit is ${env.rosterMaxMb} MB. Split it into smaller files.`);return;}const content=await input.text();if(content.includes('\0')){setError('This file contains unreadable binary data. Save it as CSV (UTF-8) and try again.');return;}if(content.includes('\uFFFD')){setError('This file is not valid UTF-8. Save it as CSV (UTF-8) and try again.');return;}const parsed=Papa.parse<Record<string,string>>(content,{header:true,skipEmptyLines:'greedy'});if(parsed.errors.length){setError('We couldn’t read this CSV. Check the header row and try again.');return;}if(parsed.data.length>env.rosterMaxRows){setError(`This file has more than ${env.rosterMaxRows.toLocaleString()} rows. Split it into smaller files.`);return;}const fields=parsed.meta.fields??[];setFile(input);setText(content);setHeaders(fields);setColumnMap(Object.fromEntries(canonicalHeaders.map((key)=>[key,guessColumn(fields,key)])));setStep(2);};
  const runCheck=async()=>{setError('');const nameColumn=columnMap.full_name;const identityColumn=columnMap.email||columnMap.student_id_number;if(!nameColumn||!identityColumn){setError('Map Name and at least one of Email or Student ID before continuing.');return;}const result=parseRosterCsv(text,columnMap);setRows(result.rows);setErrors(result.errors);if(!result.rows.length){setError('No valid rows were found. Fix the mapping or download the error report.');setStep(3);return;}setBusy(true);try{const dry=await backend.roster.importRows(result.rows,true);setServerReport(dry);setStep(3);}catch{setError('We couldn’t check this roster. Check your connection and try again.');}finally{setBusy(false);}};
  const importValid=async()=>{setError('');setBusy(true);try{const real=await backend.roster.importRows(rows,false);setReport(real);setStep(4);await client.invalidateQueries({queryKey:['roster']});await client.invalidateQueries({queryKey:['students']});}catch{setError('We couldn’t import this roster. Check your connection and try again.');}finally{setBusy(false);}};
  const cancel=()=>{setFile(null);setText('');setHeaders([]);setRows([]);setErrors([]);setServerReport(null);setReport(null);setStep(1);};
  const mappedCsv=rows.length?buildCanonicalCsv(rows):'';
  const loadPage=<PageWrap><PageTitle title="Upload roster" description="Check and prepare your CSV before it reaches AptoHire."/><ol className="wizard-steps" aria-label="Import steps">{['Choose file','Map columns','Check','Result'].map((label,index)=><li className={`wizard-step${step===index+1?' active':''}`} aria-current={step===index+1?'step':undefined} key={label}>Step {index+1}: {label}</li>)}</ol>{error?<div className="error-message" role="alert">{error}</div>:null}
  {step===1?<section className="panel import-panel"><h2>Choose a CSV file</h2><p>CSV only, UTF-8, up to {env.rosterMaxMb} MB and {env.rosterMaxRows.toLocaleString()} rows. Excel files (.xlsx) aren’t supported. Save as CSV.</p><div className="dropzone"><FileUp size={28}/><p><strong>{file?.name ?? 'Choose your roster file'}</strong></p><input type="file" accept=".csv,text/csv,application/vnd.ms-excel" aria-label="Choose CSV file" onChange={(e)=>void chooseFile(e.target.files?.[0]??null)}/></div><p className="small muted">Your student IDs are converted to a secure fingerprint before they are stored.</p><a className="text-link" href="/samples/roster-sample-clean.csv" download>Download a sample CSV <Download size={16}/></a></section>:null}
  {step===2?<section className="section"><h2>Map columns</h2><p className="section-note">Choose which file column matches each field. Only mapped columns are used.</p><div className="privacy-note"><LockKeyhole size={17}/>Columns you don’t map are removed in your browser and never uploaded.</div><div className="mapping-grid">{canonicalHeaders.map((field)=>{const labels:Record<string,string>={full_name:'Name',email:'Email',student_id_number:'Student ID',program:'Program',program_level:'Program level',year:'Year',status:'Status'};return <label className="field" key={field}><span>{labels[field]}{field==='full_name'?' · required':''}</span><select value={columnMap[field]??''} onChange={(e)=>setColumnMap({...columnMap,[field]:e.target.value})}><option value="">Don’t map</option>{headers.map((header)=><option value={header} key={header}>{header}</option>)}</select></label>;})}</div><h3>Preview</h3><div className="table-wrap"><table className="data-table"><caption className="sr-only">First five rows of the selected file</caption><thead><tr>{headers.map((header)=><th scope="col" key={header}>{header}</th>)}</tr></thead><tbody>{Papa.parse<Record<string,string>>(text,{header:true,skipEmptyLines:'greedy'}).data.slice(0,5).map((row,index)=><tr key={index}>{headers.map((header)=><td key={header}>{row[header]}</td>)}</tr>)}</tbody></table></div><div className="modal-actions"><Button variant="secondary" onClick={cancel}>Cancel</Button><Button variant="secondary" onClick={()=>setStep(1)}>Back</Button><Button onClick={()=>void runCheck()} loading={busy}>Check roster</Button></div></section>:null}
  {step===3?<section className="section"><h2>Review the check</h2><p className="section-note">Fix the column mapping or import valid rows only. Unmapped columns stay in your browser.</p><div className="stat-row"><div className="stat"><span className="stat-value">{serverReport?.total??rows.length}</span><span className="stat-label">Total rows</span></div><div className="stat"><span className="stat-value">{serverReport?.valid??rows.length}</span><span className="stat-label">Valid rows</span></div><div className="stat"><span className="stat-value">{invalidRowCount([...errors,...(serverReport?.invalid??[])])}</span><span className="stat-label">Rows with issues</span></div><div className="stat"><span className="stat-value">{serverReport?.duplicates??0}</span><span className="stat-label">Duplicates</span></div></div>{errors.length||serverReport?.invalid.length?<><h3>Rows to fix or skip</h3><div className="table-wrap"><table className="data-table"><caption className="sr-only">Roster validation errors</caption><thead><tr><th scope="col">Row</th><th scope="col">Field</th><th scope="col">Issue</th></tr></thead><tbody>{[...errors,...(serverReport?.invalid??[])].slice(0,100).map((item,index)=><tr key={`${item.row}-${item.field}-${index}`}><td>{item.row}</td><td>{item.field}</td><td>{item.reason}</td></tr>)}</tbody></table></div><Button variant="secondary" onClick={()=>downloadErrors([...errors,...(serverReport?.invalid??[])])}><Download size={16}/>Download error report</Button></>:<div className="success-message"><Check size={18}/>No client-side issues found.</div>}<p className="small muted">{serverReport?.created??rows.length} rows will be created · {serverReport?.updated??0} will be updated. Only the canonical fields are prepared for import.</p><details className="small"><summary>Preview of the minimal CSV sent</summary><pre className="csv-preview">{mappedCsv.split('\n').slice(0,6).join('\n')}</pre></details><div className="modal-actions"><Button variant="secondary" onClick={cancel}>Cancel import</Button><Button variant="secondary" onClick={()=>setStep(2)}>Back to mapping</Button><Button onClick={()=>void importValid()} loading={busy}>Import valid rows</Button></div></section>:null}
  {step===4&&report?<section className="section import-result"><div className="success-icon"><Check size={24}/></div><h2>Roster imported.</h2>{uni.status==='pending'?<p>Your roster is saved. Matching and student sign-ups start once your university is approved.</p>:<p>{report.created} students added, {report.updated} updated, {invalidRowCount([...errors,...report.invalid])} skipped.</p>}{uni.status==='approved'&&report.matched_existing>0?<p>{report.matched_existing} student{report.matched_existing===1?' already has':'s already have'} an AptoHire profile. We asked them to confirm their new university.</p>:null}<div className="modal-actions"><Button variant="secondary" onClick={()=>navigate('/roster')}>View roster</Button><Button onClick={cancel}>Import another file</Button></div></section>:null}</PageWrap>;
  return loadPage;
}
export function PlacementsPage() {
  const uni=usePageUni();const backend=useBackend();const students=useStudents();const placements=useQuery({queryKey:['placements',uni.id],queryFn:()=>backend.placements.list()});const client=useQueryClient();const [selected,setSelected]=useState<Student|null>(null);const [toast,setToast]=useState('');const summary=placementSummary((placements.data??[]).map((p)=>p.status));const [alumniOnly,setAlumniOnly]=useState(true);const [filter,setFilter]=useState('');const {prepare,dialog}=useExport();
  if(students.isPending||placements.isPending)return <LoadBlock/>;if(students.isError||placements.isError)return <PageWrap><ErrorState onRetry={()=>{void students.refetch();void placements.refetch();}}/></PageWrap>;
  const pMap=new Map((placements.data??[]).map((p)=>[p.student_id,p]));const rows=(students.data??[]).filter((s)=>!alumniOnly||s.status==='alumni').filter((s)=>!filter||s.placement_status===filter).map((s)=>({student:s,placement:pMap.get(s.id)}));
  const exportRows=rows.map(({student,placement})=>({Name:student.full_name,Status:student.status,Program:student.program??'',Year:student.year??'',Placement:placement?.status??'unknown',Organization:placement?.organization_name_text??'',Role:placement?.role_text??'',Source:placement?.source??'university','Last updated':placement?.updated_at??''}));
  const save=async(student:Student,status:Student['placement_status'],organization:string,role:string)=>{await backend.placements.update({student_id:student.id,status,organization_name_text:organization,role_text:role,source:'university',updated_at:new Date().toISOString()});await client.invalidateQueries({queryKey:['placements']});await client.invalidateQueries({queryKey:['students']});setSelected(null);setToast('Placement updated.');window.setTimeout(()=>setToast(''),3000);};
  return <PageWrap><PageTitle title="Placements" description="Track known outcomes. Unknown doesn’t mean not placed." actions={<ExportButton onClick={()=>prepare('placements',exportRows)}/>}/>{uni.status==='pending'?<PendingNote/>:null}<StatRow items={[{label:'Placed',value:summary.placed},{label:'Not placed',value:summary.notPlaced},{label:'Unknown',value:summary.unknown},{label:'Placed',value:summary.placedPercent,detail:'of students with a known outcome'}]}/><div className="privacy-note"><Info size={17}/>Unknown means we don’t have an outcome yet. It doesn’t mean not placed.</div><div className="filter-row"><label className="filter-checkbox"><input type="checkbox" checked={alumniOnly} onChange={(e)=>setAlumniOnly(e.target.checked)}/> Alumni only</label><select className="filter-select" aria-label="Filter placement status" value={filter} onChange={(e)=>setFilter(e.target.value)}><option value="">All placement outcomes</option><option value="placed">Placed</option><option value="not_placed">Not placed</option><option value="unknown">Unknown</option></select></div><div className="table-wrap"><table className="data-table"><caption className="sr-only">Student placement outcomes</caption><thead><tr>{['Name','Status','Program / year','Placement','Organization','Role','Source','Last updated',''].map((label,index)=><th scope="col" key={`${label}-${index}`}>{label}</th>)}</tr></thead><tbody>{rows.slice(0,25).map(({student,placement})=><tr key={student.id}><td className="table-name">{student.full_name}</td><td>{student.status}</td><td>{student.program??'—'} / {student.year??'—'}</td><td><PlacementChip status={placement?.status??'unknown'}/></td><td>{placement?.organization_name_text||'—'}</td><td>{placement?.role_text||'—'}</td><td>{placement?.source==='student'?'Student confirmation':'University'}</td><td>{placement?.updated_at?new Date(placement.updated_at).toLocaleDateString('en-IN',{day:'numeric',month:'short'}):'—'}</td><td>{!student.claimed?<span className="small muted">Unknown (not registered)</span>:uni.status==='approved'?<Button variant="secondary" onClick={()=>setSelected(student)}>Update</Button>:<Button variant="secondary" disabled title="Available after approval">Update</Button>}</td></tr>)}</tbody></table><div className="table-mobile">{rows.slice(0,25).map(({student,placement})=><div className="table-mobile-row" key={student.id}><strong>{student.full_name}</strong><div className="table-mobile-line"><span>Placement</span><span>{placement?.status??'unknown'}</span></div><div className="table-mobile-line"><span>Organization</span><span>{placement?.organization_name_text||'—'}</span></div><div className="table-mobile-line"><span>Source</span><span>{placement?.source==='student'?'Student confirmation':'University'}</span></div>{student.claimed?<Button variant="secondary" disabled={uni.status==='pending'} onClick={()=>setSelected(student)}>Update placement</Button>:<span className="small muted">Unknown (not registered)</span>}</div>)}</div></div>{selected?<PlacementDialog student={selected} initial={pMap.get(selected.id)} close={()=>setSelected(null)} save={save}/>:null}{dialog}{toast?<div className="toast" role="status">{toast}</div>:null}</PageWrap>;
}
function PlacementDialog({student,initial,close,save}:{student:Student;initial?:Placement;close:()=>void;save:(student:Student,status:Student['placement_status'],org:string,role:string)=>Promise<void>}) {
 const [status,setStatus]=useState<Student['placement_status']>(initial?.status??'unknown');const [organization,setOrganization]=useState(initial?.organization_name_text??'');const [role,setRole]=useState(initial?.role_text??'');const [confirm,setConfirm]=useState(false);
 return <FocusTrap onClose={close}><form className="modal" role="dialog" aria-modal="true" aria-labelledby="placement-title" onSubmit={(e)=>{e.preventDefault();if(initial?.source==='student'&&!confirm){setConfirm(true);return;}void save(student,status,organization,role);}}><h2 id="placement-title">Update placement</h2><p>{student.full_name} · Source: University</p>{initial?.source==='student'&&confirm?<div className="preview-note">The student confirmed a placement outcome. Confirm that you want to replace it with a university update.</div>:null}<fieldset className="status-radio"><legend>Placement status</legend>{(['placed','not_placed','unknown'] as const).map((value)=><label key={value}><input type="radio" name="placement" value={value} checked={status===value} onChange={()=>setStatus(value)}/>{value==='placed'?'Placed':value==='not_placed'?'Not placed':'Unknown'}</label>)}</fieldset><label className="field"><span>Organization name</span><input value={organization} maxLength={80} onChange={(e)=>setOrganization(e.target.value)}/></label><label className="field"><span>Role</span><input value={role} maxLength={80} onChange={(e)=>setRole(e.target.value)}/></label><div className="modal-actions"><Button variant="secondary" type="button" onClick={close}>Cancel</Button><Button type="submit">Save placement</Button></div></form></FocusTrap>;
}
export function SkillsPage() {
  const location=useLocation();const uni=usePageUni();const overview=useOverview();const demand=useDemand();const [search,setSearch]=useState('');const [family,setFamily]=useState('');const params=new URLSearchParams(location.search);const tab=params.get('tab')??'supply';
  const setTab=(next:string)=>{params.set('tab',next);window.history.replaceState(null,'',`${location.pathname}?${params.toString()}`);window.dispatchEvent(new PopStateEvent('popstate'));};
  const skills=(overview.data?.skills??[]).filter((s)=>s.name.toLowerCase().includes(search.toLowerCase())&&(!family||s.family===family));
  const familyNames=[...new Set((overview.data?.skills??[]).map((skill)=>skill.family))];
  return <PageWrap><PageTitle title="Skills demand" description="Understand verified skill supply and organization demand."/>{uni.status==='pending'?<PendingNote/>:null}<div className="tabs" role="tablist" aria-label="Skills views"><button className={`tab-link${tab==='supply'?' active':''}`} role="tab" aria-selected={tab==='supply'} onClick={()=>setTab('supply')}>Supply vs demand</button><button className={`tab-link${tab==='unmatched'?' active':''}`} role="tab" aria-selected={tab==='unmatched'} onClick={()=>setTab('unmatched')}>Unmatched demand</button><button className={`tab-link${tab==='gaps'?' active':''}`} role="tab" aria-selected={tab==='gaps'} onClick={()=>setTab('gaps')}>Curriculum gaps</button></div>
  {tab==='supply'?<section className="section" role="tabpanel"><div className="filter-row"><div className="searchbox"><Search size={18}/><label className="sr-only" htmlFor="skill-search">Search skills</label><input id="skill-search" className="input" placeholder="Search skills" value={search} onChange={(e)=>setSearch(e.target.value)}/></div><select className="filter-select" aria-label="Filter skill family" value={family} onChange={(e)=>setFamily(e.target.value)}><option value="">All families</option>{familyNames.map((name)=><option key={name}>{name}</option>)}</select></div>{overview.isPending?<Spinner/>:overview.isError?<ErrorState onRetry={()=>void overview.refetch()}/>:skills.length?<SkillTable skills={skills}/>:<EmptyState title="No skills match your search."/>}</section>:null}
  {tab==='unmatched'?<section className="section" role="tabpanel"><div className="privacy-note"><LockKeyhole size={17}/>You see counts and reasons only. Student identities are never shown here.</div>{demand.isPending?<Spinner/>:demand.isError?<ErrorState onRetry={()=>void demand.refetch()}/>:demand.data?.length?<DemandPreview rows={demand.data}/>:<EmptyState title="No unmatched demand right now."/>}</section>:null}
  {tab==='gaps'?<section className="section" role="tabpanel"><p className="section-note">A gap means more jobs ask for a skill than students are verified in it. It’s a signal, not a score.</p>{overview.isPending?<Spinner/>:overview.isError?<ErrorState onRetry={()=>void overview.refetch()}/>:<div className="gap-list">{[...(overview.data?.skills??[])].sort((a,b)=>b.open_jobs-a.open_jobs).map((skill)=>{const label=gapLabel(skill.verified_students,skill.open_jobs);const ratio=skill.open_jobs?Math.min(100,skill.verified_students/skill.open_jobs*100):100;return <div className="gap-row" key={skill.id}><div className="gap-heading"><div><strong>{skill.name}</strong><span className="small muted"> · {skill.open_jobs} open jobs · {skill.verified_students} verified students</span></div><Chip tone={label==='Covered'?'verified':label==='Some gap'?'pending':'outline'}>{label}</Chip></div><div className="funnel-track"><div className="funnel-bar" style={{width:`${ratio}%`,background:label==='Covered'?'var(--verdant-600)':'var(--ember-500)'}}/></div></div>;})}</div>}</section>:null}
  </PageWrap>;
}
export function DirectoryPage() {
 const uni=usePageUni();const backend=useBackend();const query=useQuery({queryKey:['directory'],queryFn:()=>backend.directory.list()});const [search,setSearch]=useState('');const [kind,setKind]=useState('');const [selected,setSelected]=useState<Organization|null>(null);
 const orgs=(query.data??[]).filter((org)=>org.name.toLowerCase().includes(search.toLowerCase())&&(!kind||org.kind===kind));
 if(query.isPending)return <LoadBlock/>;if(query.isError)return <PageWrap><ErrorState onRetry={()=>void query.refetch()}/></PageWrap>;
 return <PageWrap><PageTitle title="Organizations" description="Explore organizations and their public job posts."/>{uni.status==='pending'?<PendingNote/>:null}<div className="filter-row"><div className="searchbox"><Search size={18}/><label className="sr-only" htmlFor="directory-search">Search organizations</label><input id="directory-search" className="input" placeholder="Search organizations" value={search} onChange={(e)=>setSearch(e.target.value)}/></div><select className="filter-select" aria-label="Filter organization kind" value={kind} onChange={(e)=>setKind(e.target.value)}><option value="">All kinds</option>{[...new Set((query.data??[]).map((org)=>org.kind))].map((value)=><option key={value}>{value}</option>)}</select></div>{orgs.length?orgs.map((org)=><article className="directory-row" key={org.id}><div className="directory-main"><div className="org-mark"><Building2 size={21}/></div><div><h3>{org.name}</h3><p className="small muted">{org.kind} · {org.size} · {org.open_jobs} open jobs</p><Chip tone="roster"><ShieldCheck size={14}/>Verified organization</Chip></div></div><div className="directory-actions"><a className="button button-ghost" href={org.website} target="_blank" rel="noopener noreferrer">Website <ExternalLink size={15}/></a><Button variant="secondary" onClick={()=>setSelected(org)}>View jobs</Button></div></article>):<EmptyState title="No organizations yet."/>}{selected?<FocusTrap onClose={()=>setSelected(null)}><section className="modal organization-modal" role="dialog" aria-modal="true" aria-labelledby="org-title"><button className="modal-close icon-button" aria-label="Close organization details" onClick={()=>setSelected(null)}><X/></button><h2 id="org-title">{selected.name}</h2><Chip tone="roster"><ShieldCheck size={14}/>Verified organization</Chip><p className="muted">{selected.kind} · {selected.size}</p><h3>Job posts</h3>{selected.jobs.length?selected.jobs.map((job)=><div className="org-jobs" key={job.id}><div className="org-job"><strong>{job.title}</strong><span className="chip chip-muted">{job.status}</span></div><p className="small muted">{job.mode} · {job.location}</p>{job.skills.length?<p className="small">Skills: {job.skills.join(' · ')}</p>:null}</div>):<p className="muted">No public job posts yet.</p>}<div className="modal-actions"><Button variant="secondary" onClick={()=>setSelected(null)}>Close</Button></div></section></FocusTrap>:null}</PageWrap>;
}
export function NotificationsPage() {
 const backend=useBackend();const uni=usePageUni();const query=useQuery({queryKey:['notifications',uni.id],queryFn:()=>backend.notifications.list()});const client=useQueryClient();
 if(query.isPending)return <LoadBlock/>;if(query.isError)return <PageWrap><ErrorState onRetry={()=>void query.refetch()}/></PageWrap>;
 const notes=query.data??[];const today=new Date().toDateString();const todayNotes=notes.filter((note)=>new Date(note.created_at).toDateString()===today);const earlier=notes.filter((note)=>new Date(note.created_at).toDateString()!==today);
 return <PageWrap><PageTitle title="Notifications" description="Updates for your university account." actions={<Button variant="secondary" onClick={async()=>{await backend.notifications.markRead();await client.invalidateQueries({queryKey:['notifications']});}}>Mark all as read</Button>}/>{notes.length===0?<EmptyState title="You’re all caught up."/>:<><section className="section"><h2>Today</h2>{todayNotes.length?todayNotes.map((note)=><article className="notification-row" key={note.id}><span className="notice-icon"><BellIcon kind={note.kind}/></span><div><h3>{note.title}</h3><p>{note.detail}</p><span className="small muted">{new Date(note.created_at).toLocaleTimeString('en-IN',{hour:'numeric',minute:'2-digit'})}</span></div>{!note.read_at?<span className="unread-dot" role="img" aria-label="Unread"/>:null}</article>):<p className="muted">No updates today.</p>}</section><section className="section"><h2>Earlier</h2>{earlier.map((note)=><article className="notification-row" key={note.id}><span className="notice-icon"><BellIcon kind={note.kind}/></span><div><h3>{note.title}</h3><p>{note.detail}</p><span className="small muted">{new Date(note.created_at).toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'})}</span></div>{!note.read_at?<span className="unread-dot" role="img" aria-label="Unread"/>:null}</article>)}</section></>}</PageWrap>;
}
function BellIcon({kind}:{kind:string}){return kind==='demand_alert'?<Activity size={18}/>:kind==='student_registered'?<Users size={18}/>:<ClipboardList size={18}/>;}
export function AccountPage() {
 const backend=useBackend();const auth=useAuth();const uni=usePageUni();const client=useQueryClient();const [message,setMessage]=useState('');const [error,setError]=useState('');const [busy,setBusy]=useState(false);const {data:account}=useQuery({queryKey:['account',auth.user?.email],queryFn:()=>backend.account.current()});
 const globalSignout=async()=>{await auth.signOut('global');window.location.assign('/login');};
 const password=async(form:HTMLFormElement)=>{setError('');setMessage('');const data=new FormData(form);const value=String(data.get('password')??'');if(value.length<10){setError('Use at least 10 characters for your password.');return;}setBusy(true);try{await backend.auth.updatePassword(value);setMessage('Password updated.');form.reset();}catch{setError('We couldn’t update your password. Check your connection and try again.');}finally{setBusy(false);}};
 return <PageWrap><PageTitle title="Account & security" description="Manage your sign-in and university account."/><section className="section"><h2>Account</h2><div className="account-detail"><span>Email</span><strong>{account?.email??auth.user?.email}</strong><span className="small muted">To change this address, contact support.</span></div><div className="account-detail"><span>University</span><strong>{uni.name}</strong><span>{uni.status==='approved'?<Chip tone="approved">Approved</Chip>:<Chip tone="pending">Pending</Chip>}</span></div></section><section className="section"><h2>Change password</h2>{error?<div className="error-message" role="alert">{error}</div>:null}{message?<div className="success-message" role="status">{message}</div>:null}<form className="password-form" onSubmit={(e)=>{e.preventDefault();void password(e.currentTarget);}}><label className="field"><span>New password</span><input name="password" type="password" autoComplete="new-password" minLength={10}/></label><Button type="submit" loading={busy}>Update password</Button></form></section><section className="section"><h2>Sessions</h2><p className="muted">Sign out on this device or end sessions on all devices.</p><Button variant="secondary" onClick={()=>void globalSignout()}><LogOutIcon/>Sign out of all devices</Button></section>{demoEnabled?<section className="section demo-tools"><h2>Demo tools</h2><p className="muted">These controls only affect fictional demo data.</p><div className="page-actions"><Button variant="secondary" onClick={async()=>{await backend.university.resetDemo();await client.invalidateQueries();setMessage('Demo data reset.');}}><Activity size={17}/>Reset demo data</Button>{uni.status==='pending'?<Button onClick={async()=>{await backend.university.simulateApproval();await client.invalidateQueries();setMessage('Your university is approved.');}}><Check size={17}/>Simulate admin approval</Button>:null}</div></section>:null}</PageWrap>;
}
function LogOutIcon(){return <X size={17}/>;}
export function HelpPage() {
 return <PageWrap><PageTitle title="Help" description="A few notes to help you work with your university data."/><section className="section help-list"><details open><summary>How does the roster work?</summary><p>Your roster is a list of students associated with your university. AptoHire updates only its own affiliation records when you change a student’s year or lifecycle status. It never edits your university’s master records.</p></details><details><summary>What does “Verified via roster” mean?</summary><p>The student’s account is linked to a row from your university roster. It shows how the affiliation was confirmed.</p></details><details><summary>How do placements work?</summary><p>Set Placed, Not placed or Unknown. Unknown means there is no outcome yet. It is not counted as Not placed.</p></details><details><summary>What does unmatched demand show?</summary><p>It shows skill names, job counts and reason counts only. Student identities are never shown in demand views.</p></details><details><summary>How is student data protected?</summary><p>You can see only students belonging to your university. Project files and videos stay private to the student.</p></details></section><section className="section"><h2>Contact support</h2><p>Need help with your account or a roster upload?</p><a className="button button-secondary" href={`mailto:${env.supportEmail}`}>Email {env.supportEmail}</a></section><section className="section help-links"><a href={rootUrl('/privacy')}>Privacy <ExternalLink size={15}/></a><a href={rootUrl('/terms')}>Terms <ExternalLink size={15}/></a><a href={rootUrl('/ai-and-fairness')}>AI and fairness <ExternalLink size={15}/></a></section></PageWrap>;
}
export function MissingPage(){return <PageWrap><div className="missing-state"><div className="stat-value">404</div><h1>That page doesn’t exist.</h1><p className="muted">Check the address or return to your overview.</p><Link className="button button-primary" to="/">Go home</Link></div></PageWrap>;}
